/**
 * A browser subscription as handed over by ``pushManager.subscribe()``.
 */
export type PushSubscriptionCreate = {
    endpoint: string;
    keys: PushSubscriptionKeys;
    user_agent?: string;
};

/**
 * Identifies the subscription to drop.
 */
export type PushSubscriptionDelete = {
    endpoint: string;
};

/**
 * The two client keys the payload is encrypted with.
 */
export type PushSubscriptionKeys = {
    p256dh: string;
    auth: string;
};

/**
 * Read-only view of the push channel for the current user.
 */
export type PushSubscriptionStatus = {
    /**
     * Whether this deployment has VAPID keys and can send push at all.
     */
    configured: boolean;
    /**
     * Number of browsers this user has subscribed.
     */
    device_count: number;
};

/**
 * Read-only minimal representation of a federated RemoteActor.
 */
export type RemoteActorMinimal = {
    readonly ap_id: string;
    readonly username: string;
    readonly display_name: string;
};

/**
 * * `h` - Stündlich
 * * `d` - Täglich
 * * `w` - Wöchentlich
 */
export type RentalPeriodEnum = 'h' | 'd' | 'w';

/**
 * * `sell` - Sell
 * * `donate` - Donate
 * * `rent` - Rent
 * * `borrow` - Ausleihen
 * * `want_buy` - Want to Buy
 * * `want_rent` - Want to Rent
 */
export type SalesTypeEnum = 'sell' | 'donate' | 'rent' | 'borrow' | 'want_buy' | 'want_rent';

/**
 * The full set of search facets, each excluding its own active filter.
 */
export type SearchFacets = {
    types: Array<TypeFacet>;
    categories: Array<CategoryFacet>;
    collections: Array<CollectionFacet>;
    availability: Array<AvailabilityFacet>;
    owners: Array<OwnerFacet>;
};

/**
 * * `0` - Entwurf
 * * `2` - Verfügbar
 * * `3` - Reserviert
 * * `4` - Rented
 * * `5` - Verkauft
 * * `6` - Archived
 */
export type Status7D3Enum = 0 | 2 | 3 | 4 | 5 | 6;

/**
 * * `1` - Ausstehend
 * * `2` - Abgebrochen
 * * `3` - Bestätigt
 * * `4` - Abgeschlossen
 * * `5` - Abgelehnt
 * * `6` - In Progress
 */
export type StatusD02Enum = 1 | 2 | 3 | 4 | 5 | 6;

/**
 * A type value (rent | buy | wanted) and its matching visible item count.
 */
export type TypeFacet = {
    value: string;
    count: number;
};

export type User = {
    readonly id: string;
    /**
     * Benutzername
     *
     * Erforderlich. 150 Zeichen oder weniger. Nur Buchstaben, Ziffern und @/./+/-/_.
     */
    username: string;
    /**
     * Name des Benutzers
     */
    name?: string;
    /**
     * E-Mail-Adresse
     */
    email?: string | string;
};

export type Version = {
    git_sha: string;
    version: string;
};

/**
 * * `0` - Öffentlich
 * * `1` - Authenticated
 * * `2` - Specific
 * * `3` - Private
 */
export type VisibilityEnum = 0 | 1 | 2 | 3;

/**
 * Full serializer for Book detail view.
 *
 * Read-side: exposes isbn, language, year, topic, metadata, authors,
 * genres, verlag (publisher name), shelf from Item.properties.
 *
 * Write-side: accepts authors (list of strings), genres (list of strings),
 * publisher (string), shelf (string), isbn, language, year, topic,
 * metadata.  The old UUID-based author_ids / genre_ids / verlag_id /
 * shelf_id fields are no longer accepted.
 */
export type BookWritable = {
    price?: string | null;
    isbn_write?: string;
    language_write?: string;
    year_write?: number | null;
    topic_write?: string;
    metadata_write?: unknown;
    authors_write?: Array<string>;
    genres_write?: Array<string>;
    publisher?: string;
    shelf_write?: string;
    /**
     * Category of the item
     *
     * * `books` - Bücher
     * * `clothing` - Kleidung
     * * `electronics` - Elektronik
     * * `furniture` - Möbel
     * * `garden` - Garten
     * * `kitchen` - Küche
     * * `other` - Andere
     * * `rooms` - Räume
     * * `sports` - Sport
     * * `tools` - Werkzeuge
     * * `toys` - Spielzeug
     * * `vehicles` - Fahrzeuge
     */
    category?: CategoryEnum | BlankEnum;
    name?: string;
    slug?: string | string;
    description?: string;
    /**
     * Interner Artikel, nicht für öffentliche Anzeige
     */
    internal?: boolean;
    /**
     * Kontaktinformationen öffentlich anzeigen
     */
    display_contact?: boolean;
    /**
     * How the item is offered: Sell, Donate, Rent, Borrow, Want to Buy, or Want to Rent.
     *
     * * `sell` - Sell
     * * `donate` - Donate
     * * `rent` - Rent
     * * `borrow` - Ausleihen
     * * `want_buy` - Want to Buy
     * * `want_rent` - Want to Rent
     */
    sales_type: SalesTypeEnum;
    /**
     * Defines the period the rental price applies to (hourly, daily, weekly). Used for price calculation and display formatting.
     *
     * * `h` - Stündlich
     * * `d` - Täglich
     * * `w` - Wöchentlich
     */
    rental_period?: RentalPeriodEnum | BlankEnum;
    /**
     * Selbstbedienungsvermietung ohne Zustimmung des Eigentümers erlauben
     */
    rental_self_service?: boolean;
    /**
     * Unbefristete Vermietungen ohne Rückgabedatum erlauben
     */
    rental_open_end?: boolean;
    /**
     * Zahlung über internes Zahlungssystem aktivieren
     */
    payment_enabled?: boolean;
    /**
     * Condition of the item
     *
     * * `0` - Neu
     * * `1` - Gebraucht
     * * `2` - Kaputt
     */
    condition?: ConditionEnum;
    active?: boolean;
    status?: Status7D3Enum;
    /**
     * Who can see this item: Public (everyone), Authenticated (logged-in users), Specific (selected users/groups), or Private (owner and co-owners only).
     *
     * * `0` - Öffentlich
     * * `1` - Authenticated
     * * `2` - Specific
     * * `3` - Private
     */
    visibility?: VisibilityEnum;
    /**
     * Category-specific properties stored as JSONB. For books: isbn, language, year, topic, metadata, authors, genres, publisher, shelf.
     */
    properties?: unknown;
    /**
     * Controls whether this item is shared via ActivityPub federation. 'Public (federated)' shares it with allowed peer instances. 'Local only' keeps it on this instance only.
     *
     * * `public_federated` - Public (federated)
     * * `local_only` - Local only
     */
    federation_visibility?: FederationVisibilityEnum;
    /**
     * Where the item is currently kept. Leave blank when the item is at the owner's own place (the default).
     */
    location?: string | null;
};

